// RGB LED (ortak katot): renk karışımı
const int KIRMIZI = 9;
const int YESIL = 10;
const int MAVI = 11;

void renk(int k, int y, int m) {
  analogWrite(KIRMIZI, k);
  analogWrite(YESIL, y);
  analogWrite(MAVI, m);
}

void setup() {
  pinMode(KIRMIZI, OUTPUT);
  pinMode(YESIL, OUTPUT);
  pinMode(MAVI, OUTPUT);
}

void loop() {
  renk(255, 0, 0);       // kırmızı
  delay(1000);
  renk(0, 255, 0);       // yeşil
  delay(1000);
  renk(0, 0, 255);       // mavi
  delay(1000);
  renk(255, 255, 0);     // sarı
  delay(1000);
  renk(255, 0, 255);     // mor
  delay(1000);
  renk(0, 255, 255);     // turkuaz
  delay(1000);
  renk(255, 255, 255);   // beyaz
  delay(1000);
}
